package in.kabadiwala.connect.model; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.time.*; @Document("pickups") public class Pickup { @Id public String id; @Indexed(unique=true) public String lotId; @Indexed public String collectorId,recyclerId; public String address,status="SCHEDULED"; public LocalDate date; public String timeWindow; public String handoverCodeHash; public Instant handoverCodeExpiresAt; public int handoverAttempts; public boolean handoverUsed; public Double finalWeight,finalAmount; @CreatedDate public Instant createdAt; @LastModifiedDate public Instant updatedAt; }